/**
 * Message communication type definitions
 */

export interface WebViewMessage {
  /** Message type identifier */
  type: string
  
  /** Message payload data */
  payload?: any
  
  /** Unique message ID for tracking */
  id?: string
  
  /** Message timestamp */
  timestamp?: number
  
  /** Origin domain of the message */
  origin?: string
  
  /** Target frame ID (for multi-frame scenarios) */
  targetFrame?: string
  
  /** Message priority level */
  priority?: MessagePriority
  
  /** Whether this message expects a response */
  expectsResponse?: boolean
  
  /** Response timeout in milliseconds */
  responseTimeout?: number
}

export interface WebViewMessageResponse {
  /** Original message ID this responds to */
  messageId: string
  
  /** Response type */
  type: 'success' | 'error'
  
  /** Response data */
  data?: any
  
  /** Error information if type is 'error' */
  error?: string
  
  /** Response timestamp */
  timestamp: number
}

export enum MessagePriority {
  LOW = 0,
  NORMAL = 1,
  HIGH = 2,
  CRITICAL = 3
}

export interface MessageQueueItem {
  message: WebViewMessage
  timestamp: number
  retryCount: number
  maxRetries: number
}

export interface MessageFilter {
  /** Allowed message types */
  allowedTypes?: string[]
  
  /** Blocked message types */
  blockedTypes?: string[]
  
  /** Allowed origins */
  allowedOrigins?: string[]
  
  /** Message size limit in bytes */
  maxSize?: number
  
  /** Custom validation function */
  validator?: (message: WebViewMessage) => boolean
}

export interface MessageBridgeOptions {
  /** Enable message queuing when iframe is not ready */
  enableQueue?: boolean
  
  /** Maximum queue size */
  maxQueueSize?: number
  
  /** Message timeout in milliseconds */
  defaultTimeout?: number
  
  /** Enable message compression */
  enableCompression?: boolean
  
  /** Message filters */
  messageFilter?: MessageFilter
  
  /** Enable debug logging */
  debugMode?: boolean
}

export interface MessageStats {
  /** Total messages sent */
  messagesSent: number
  
  /** Total messages received */
  messagesReceived: number
  
  /** Failed message attempts */
  messagesFailed: number
  
  /** Average response time */
  averageResponseTime: number
  
  /** Queue size */
  queueSize: number
  
  /** Last activity timestamp */
  lastActivity: number
}

export type MessageCallback = (message: WebViewMessage) => void | Promise<void>
export type MessageResponseCallback = (response: WebViewMessageResponse) => void
export type MessageErrorCallback = (error: Error, message?: WebViewMessage) => void

// Pre-defined message types for common operations
export const MessageTypes = {
  // System messages
  SYSTEM_READY: 'system:ready',
  SYSTEM_ERROR: 'system:error',
  SYSTEM_PING: 'system:ping',
  SYSTEM_PONG: 'system:pong',
  
  // Code injection
  CODE_INJECT: 'code:inject',
  CODE_INJECT_RESULT: 'code:inject:result',
  
  // UI events
  UI_READY: 'ui:ready',
  UI_RESIZE: 'ui:resize',
  UI_CLOSE: 'ui:close',
  
  // Bridge messages
  BRIDGE_INIT: 'bridge:init',
  BRIDGE_READY: 'bridge:ready',
  BRIDGE_ERROR: 'bridge:error',
  
  // Custom user messages
  USER_ACTION: 'user:action',
  USER_DATA: 'user:data',
  USER_CONFIG: 'user:config'
} as const

export type SystemMessageType = typeof MessageTypes[keyof typeof MessageTypes]

// Message validation helpers
export interface MessageValidator {
  validateMessage(message: any): message is WebViewMessage
  validateOrigin(origin: string, allowedOrigins: string[]): boolean
  validateType(type: string, allowedTypes?: string[]): boolean
  validateSize(message: WebViewMessage, maxSize: number): boolean
}
