/**
 * Core WebView type definitions
 */

export interface WebViewOptions {
  /** Enable transparent background for iframe */
  transparent?: boolean
  
  /** Allow script injection into iframe */
  allowScripts?: boolean
  
  /** List of trusted origins for message validation */
  trustedOrigins?: string[]
  
  /** Auto-resize iframe when window resizes */
  autoResize?: boolean
  
  /** Enable debug mode with console logging */
  debugMode?: boolean
  
  /** Timeout for iframe loading operations (ms) */
  timeout?: number
  
  /** Custom z-index for iframe positioning */
  zIndex?: number
  
  /** Custom CSS classes to apply to iframe */
  cssClasses?: string[]
  
  /** Enable pointer events on iframe */
  enablePointerEvents?: boolean
  
  /** Custom iframe sandbox attributes */
  sandbox?: string
}

export interface WebViewState {
  /** Whether the webview is currently open */
  isOpen: boolean
  
  /** Current URL loaded in the iframe */
  currentUrl: string | null
  
  /** Loading state of the iframe */
  isLoading: boolean
  
  /** Error state */
  hasError: boolean
  
  /** Last error message */
  lastError: string | null
  
  /** Timestamp of last activity */
  lastActivity: number
}

export interface WebViewPosition {
  x: number
  y: number
  width: number
  height: number
}

export interface WebViewSize {
  width: number
  height: number
}

export interface IframeCreationOptions {
  url: string
  transparent: boolean
  zIndex: number
  cssClasses: string[]
  sandbox: string
  enablePointerEvents: boolean
}

export interface CodeInjectionResult {
  success: boolean
  error?: string
  executionTime: number
}

export interface WebViewEvents {
  'open': (url: string) => void
  'close': () => void
  'load': (url: string) => void
  'error': (error: Error) => void
  'message': (message: any) => void
  'resize': (size: WebViewSize) => void
}

export type WebViewEventType = keyof WebViewEvents
export type WebViewEventCallback<T extends WebViewEventType> = WebViewEvents[T]

// Error types
export class WebViewError extends Error {
  public readonly code: string
  public readonly details?: any
  
  constructor(message: string, code: string, details?: any) {
    super(message)
    this.name = 'WebViewError'
    this.code = code
    this.details = details
  }
}

export class IframeLoadError extends WebViewError {
  constructor(url: string, details?: any) {
    super(`Failed to load iframe: ${url}`, 'IFRAME_LOAD_ERROR', details)
  }
}

export class CodeInjectionError extends WebViewError {
  constructor(message: string, details?: any) {
    super(`Code injection failed: ${message}`, 'CODE_INJECTION_ERROR', details)
  }
}

export class MessageError extends WebViewError {
  constructor(message: string, details?: any) {
    super(`Message error: ${message}`, 'MESSAGE_ERROR', details)
  }
}

export class SecurityError extends WebViewError {
  constructor(message: string, details?: any) {
    super(`Security violation: ${message}`, 'SECURITY_ERROR', details)
  }
}
